#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint   FrameCount;
    // Effect params
    float  posterize_levels;   // 2..32
    float  hue_rate;           // cycles/sec scaled by time
    float  solarize_amount;    // 0..1
    float  strobe_intensity;   // 0..1
    float  line_quantize;      // lines per band (>=1)
    float  echo_strength;      // 0..1
    float  chroma_spread;      // px shift
    float  saturation;         // 0..2
    float  contrast;           // 0..2
};

struct VSIn { float4 pos [[attribute(0)]]; float2 uv [[attribute(1)]]; };
struct VSOut { float4 pos [[position]]; float2 uv; };

vertex VSOut main0(VSIn in [[stage_in]], constant Uniforms &u [[buffer(0)]]) {
    VSOut o; o.pos = u.MVP * in.pos; o.uv = in.uv; return o;
}

static inline float3 rgb2hsv(float3 c){
    float4 K = float4(0.0, -1.0/3.0, 2.0/3.0, -1.0);
    float4 p = mix(float4(c.bg, K.wz), float4(c.gb, K.xy), step(c.b, c.g));
    float4 q = mix(float4(p.xyw, c.r), float4(c.r, p.yzx), step(p.x, c.r));
    float d = q.x - min(q.w, q.y);
    float e = 1.0e-10;
    float3 hsv;
    hsv.x = abs(q.z + (q.w - q.y) / (6.0 * d + e));
    hsv.y = d / (q.x + e);
    hsv.z = q.x;
    return hsv;
}

static inline float3 hsv2rgb(float3 c){
    float4 K = float4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
    float3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

fragment float4 fragment_main(
    VSOut in [[stage_in]],
    texture2d<float> src [[texture(0)]],
    constant Uniforms &u [[buffer(0)]]
){
    constexpr sampler smp(mag_filter::linear, min_filter::linear, address::clamp_to_edge);
    float2 uv = in.uv;

    // Line quantization (horizontal bands)
    float lines = max(1.0, u.line_quantize);
    float ypix = uv.y * u.OutputSize.y;
    float band = floor(ypix / lines);
    // Slight horizontal jitter per band for vibe
    float j = (fract(sin((band+1.23)*37.2) * 43758.5453) - 0.5) * 0.003;
    float2 uvq = float2(clamp(uv.x + j, 0.0, 1.0), (band * lines + 0.5*lines)/u.OutputSize.y);

    // Base sample
    float3 col0 = src.sample(smp, uvq).rgb;

    // Hue cycle
    float t = (float(u.FrameCount) / 60.0) * u.hue_rate; // assuming ~60fps scale
    float3 hsv = rgb2hsv(col0);
    hsv.x = fract(hsv.x + t);
    float3 col = hsv2rgb(hsv);

    // Solarize curve
    float3 solar = 0.5 - 0.5 * cos(3.14159265 * col);
    col = mix(col, solar, clamp(u.solarize_amount, 0.0, 1.0));

    // Channel strobe (cycle channels with time)
    float st = 0.5 + 0.5 * sin(t * 6.28318 * 0.5); // 0..1 slow
    float sel = floor(fract(t * 0.5) * 3.0);       // 0,1,2 over time
    float3 boost = float3(sel == 0 ? 1.0 : 0.0, sel == 1 ? 1.0 : 0.0, sel == 2 ? 1.0 : 0.0);
    col += boost * (u.strobe_intensity * st) * 0.2;

    // Chroma spread (RGB sample offsets)
    float2 px = 1.0 / u.OutputSize.xy;
    float spread = u.chroma_spread;
    float r = src.sample(smp, uvq + float2( spread, 0.0) * px).r;
    float g = src.sample(smp, uvq).g;
    float b = src.sample(smp, uvq + float2(-spread, 0.0) * px).b;
    float3 chroma = float3(r, g, b);
    col = mix(col, chroma, 0.6);

    // Echo smear (sample slight horizontal offset)
    float offs = 0.003 * (0.5 + 0.5*sin(t*3.1));
    float3 echo = src.sample(smp, float2(clamp(uvq.x - offs,0.0,1.0), uvq.y)).rgb;
    col = mix(col, echo, clamp(u.echo_strength, 0.0, 1.0));

    // Posterize
    float levels = max(2.0, u.posterize_levels);
    col = floor(col * levels) / levels;

    // Saturation/contrast
    float luma = dot(col, float3(0.299,0.587,0.114));
    col = mix(float3(luma), col, u.saturation);
    col = (col - 0.5) * max(0.0, u.contrast) + 0.5;

    return float4(saturate(col), 1.0);
}

